interface.definition:
#"SYSTEM_SYSRULES_sectionLayout_v1"(
  label: "Interview Details",
  labelColor: "SECONDARY",
  isCollapsible: true,
  contents: {
    #"SYSTEM_SYSRULES_richTextDisplayField"(
      labelPosition: "COLLAPSED",
      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
        text: "Completed by DPP Operations",
        style: "EMPHASIS"
      )
    ),
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                value: {
                  #"SYSTEM_SYSRULES_richTextHeader"(
                    text: "Interview Date & Time",
                    size: "SMALL"
                  ),
                  #"SYSTEM_SYSRULES_richTextIcon"(icon: "calendar-check-o", color: "ACCENT"),
                  "  ",
                  #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!interview.interviewDateTime)
                }
              )
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                value: {
                  #"SYSTEM_SYSRULES_richTextHeader"(
                    text: "Interviewer",
                    size: "SMALL"
                  ),
                  #"SYSTEM_SYSRULES_richTextIcon"(icon: "user-circle-o", color: "ACCENT"),
                  "  ",
                  if(
                    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!interview.interviewerId),
                    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
                    ri!interview.interviewerFirstName&" "&ri!interview.interviewerLastName
                  )
                }
              )
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                value: {
                  #"SYSTEM_SYSRULES_richTextHeader"(
                    text: "Interview Location",
                    size: "SMALL"
                  ),
                  #"SYSTEM_SYSRULES_richTextIcon"(icon: "location-arrow", color: "ACCENT"),
                  "  ",
                  #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!interview.interviewLocation)
                }
              )
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                value: {
                  #"SYSTEM_SYSRULES_richTextHeader"(
                    text: "Interview Office Location",
                    size: "SMALL"
                  ),
                  #"SYSTEM_SYSRULES_richTextIcon"(icon: "building", color: "ACCENT"),
                  "  ",
                  #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!interview.interviewOfficeLocation)
                }
              )
            )
          },
          marginBelow: "MORE",
          showDividers: true
        ),
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          labelPosition: "COLLAPSED",
          value: {
            #"SYSTEM_SYSRULES_richTextHeader"(
              text: "DPP Operations Additional Comments for Interviewer",
              size: "SMALL"
            ),
            #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!interview.comments)
          }
        )
      },
      showBorder: false
    )
  }
)
